    fn name(&self) -> &str {
        "codegen_export"
    }

    fn call(&self, args: &BTreeMap<String, String>) -> ToolOutcome {
        let target = args
            .get("framework")
            .map(|s| s.trim())
            .filter(|s| !s.is_empty())
            .unwrap_or(DEFAULT_TARGET);
        let framework = Framework::from_wire(target);
